<label><input type="radio" name="q5" value="a"> Azure Key Vault</label>
<label><input type="radio" name="q5" value="b"> Azure Storage Account</label>
<label><input type="radio" name="q5" value="c"> Azure ML Compute Instance</label>
<label><input type="radio" name="q5" value="d"> Azure Virtual Network</label>
</div>
