Check Answers
</button>

</form>

<div class="kcaz-score-box" id="kcaz-score"></div>
</div>

<script>
function gradeAzureKC(){

  var ans = {
    q1:'b',
    q2:'c',
    q3:'c',
    q4:'b',
    q5:'c',
    q6:'b'
  };

  var score = 0;
  var total = 6;

  var form = document.getElementById('kcAzure');

  ['q1','q2','q3','q4','q5','q6'].forEach(function(q){

    var sel = form.querySelector('input[name="'+q+'"]:checked');

    form.querySelectorAll('input[name="'+q+'"]').forEach(function(o){
      var l = o.parentElement;
      l.style.background = '#fff';
      l.style.borderColor = '#d0d7de';
    });

    if(sel){

      if(sel.value === ans[q]){
        sel.parentElement.style.background = '#d1fae5';
        sel.parentElement.style.borderColor = '#34d399';
        score++;
      } else {

        sel.parentElement.style.background = '#fee2e2';
        sel.parentElement.style.borderColor = '#f87171';

        var correct =
          form.querySelector('input[name="'+q+'"][value="'+ans[q]+'"]');

        correct.parentElement.style.background = '#d1fae5';
        correct.parentElement.style.borderColor = '#34d399';
      }
    }
  });

  var pct = Math.round(score/total*100);

  var box = document.getElementById('kcaz-score');
  box.style.display = 'block';

  box.style.background =
    pct === 100 ? '#d1fae5' :
    pct >= 80 ? '#e0f2fe' :
    '#fef9c3';

  box.style.border =
    '1.5px solid ' +
    (pct === 100 ? '#34d399' :
    pct >= 80 ? '#38bdf8' :
    '#fbbf24');

  box.innerHTML =
    '📊 Score: ' + score + '/' + total +
    ' (' + pct + '%) ' +
    (pct === 100
      ? '🎉 Perfect! You understand the Azure infrastructure architecture.'
      : pct >= 80
      ? '✅ Great work! You have a strong understanding of Azure services and their integration.'
      : '📚 Review the Azure Infrastructure Services section and try again.');
}
</script>
```

